+	// wire-format message must not start with big-endian uint64 zero, which
+	// is reserved as heartbeat.
+	encodeTo(w io.Writer, m raftpb.Message) error
+}
+
+type decoder interface {
+	// needReset returns whether it needs to reset in-using internal
